import networkx as nx
import itertools

def is_girth_at_least_5(G):
    for node in G.nodes():
        # BFS to find shortest cycle
        dist = {node: 0}
        queue = [node]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    # Found a cycle
                    if dist[u] + dist[v] + 1 < 5:
                        return False
    return True

def find_graph():
    # Try to build a graph with 19 vertices, girth >= 5, 5-colorable, >= 25 edges
    # A simple way is to start with a known graph and add edges
    # Or use a random approach
    import random

    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(19))
        edges = []
        # Try to add edges randomly while maintaining girth >= 5
        # A simple way: add edges one by one and check girth
        possible_edges = list(itertools.combinations(range(19), 2))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            G.add_edge(u, v)
            if not is_girth_at_least_5(G):
                G.remove_edge(u, v)
            else:
                edges.append((u, v))

            if len(edges) >= 25:
                # Check if 5-colorable
                if nx.coloring.greedy_color(G, strategy='largest_first').values():
                    max_color = max(nx.coloring.greedy_color(G, strategy='largest_first').values()) + 1
                    if max_color <= 5:
                        return edges

    return None

