def is_girth_at_least_5(adj, n):
    for start_node in range(n):
        # BFS to find shortest cycle
        dist = [-1] * n
        parent = [-1] * n
        dist[start_node] = 0
        queue = [start_node]

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    if dist[u] + dist[v] + 1 < 5:
                        return False
    return True

def is_k_colorable(adj, n, k):
    # Simple backtracking for coloring
    colors = [-1] * n
    def can_color(u):
        if u == n:
            return True
        for c in range(k):
            if all(colors[v] != c for v in adj[u]):
                colors[u] = c
                if can_color(u + 1):
                    return True
                colors[u] = -1
        return False
    return can_color(0)

